// ---- writer: collect, then commit (growing the grid if asked, honouring protection and keep boxes) ----------------
function writer() {
  const m = new Map();
  return {
    put(x, y, z, [block, state] = [], { onlyAir = false } = {}) { m.set(`${x},${y},${z}`, { pos: [x, y, z], block, state, onlyAir }); },
    erase(x, y, z) { m.delete(`${x},${y},${z}`); },
    get: (x, y, z) => m.get(`${x},${y},${z}`),
    has: (x, y, z) => m.has(`${x},${y},${z}`),
    entries: () => m.values(),
    commit(g, { grow = true, protect, keep = [] }) {
      const all = [...m.values()];
      const lo = [0, 1, 2].map((i) => Math.min(0, ...all.map((e) => e.pos[i]))), hi = [0, 1, 2].map((i) => Math.max(g.size[i] - 1, ...all.map((e) => e.pos[i])));
      const shift = lo.map((v) => (v < 0 ? -v : 0));
      if (shift.some(Boolean) || hi.some((v, i) => v >= g.size[i])) {
        if (!grow) throw new Error(`roof: does not fit the grid (needs ${lo} .. ${hi}); pass grow: true`);
        g.resize(hi.map((v, i) => v + shift[i] + 1), shift);
      }
      const inKeep = (p) => keep.some((b) => p.every((v, i) => v >= Math.min(b.from[i], b.to[i]) && v <= Math.max(b.from[i], b.to[i])));
      let cells = 0, refused = 0;
      for (const e of all) {
        if (inKeep(e.pos)) { refused++; continue; }
        const p = e.pos.map((v, i) => v + shift[i]);
        if (protect?.has(p.join(","))) { refused++; continue; }
        if (e.onlyAir && !AIR.test(g.blockAt(...p))) continue;
        if (e.block === "air") g.unset(...p); else g.set(...p, e.block, e.state);
        cells++;
      }
      return { cells, refused, shift };
    },
  };
