// Every band is a roofBand (vocab.mjs): shed style, low = the court side, palette RoofTile. The compluvium void
// (x15..20, z12..17, y6..9) stays open: no band covers it (RC and RD stop at x14 and x21, RA/RB stop at z11/z18).
// Nothing else is placed above y5 here, except the pediment at the pocket.
import { roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { pediment, ROOF_MATERIAL, ROOF_TILE } from "../vocab.mjs";

