// street side, x=36, z=48) and on the compluvium's edge (x=15, z=11/18), so the tool would grow the grid and shift every
// plan coordinate, or fill the void. Flush eaves keep both out. grow:false makes any out-of-grid cell throw, not shift.
const band = (g, rects, low) => roof(g, rects, "shed", { y: 6, low, material: ROOF_MATERIAL, soffit: ROOF_TILE, overhang: 0, edges: false, grow: false });

